export const GLOBAL_CHANNELS: Channel[] = RAW_CHANNELS.map((item) => {
  const [id, name, logo, url, backupUrl, youtubeId, category, country, language, globalCategory, isPrem] = item;
  const fallbackUrls = [url];
  if (backupUrl && backupUrl !== url) fallbackUrls.push(backupUrl);
  return {
    id,
    name,
    logo,
    url,
    backupUrl: backupUrl || undefined,
    fallbackUrls,
    youtubeId: youtubeId || undefined,
    category,
    country,
    language,
    isLive: true,
    globalCategory,
    streamType: "hls",
    quality: "1080p",
    isHd: true,
    status: isPrem ? "PREMIUM" : "FREE",
    isPremium: Boolean(isPrem),
    isEnabled: true,
  };
});

